CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE TYPE public.app_role AS ENUM('admin','user');
CREATE TYPE public.gl_account AS ENUM('debtors','membership_income','tournament_income','national_body_income','league_fees_income','visitor_income','fee_income');
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.uid',true),'')::uuid $$;
CREATE FUNCTION has_role(uuid,app_role) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION is_club_chairman(uuid,uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT $1='33333333-3333-3333-3333-333333333333'::uuid AND $2='11111111-1111-1111-1111-111111111111'::uuid $$;
CREATE FUNCTION chairman_financial_write_allowed(uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT auth.uid() IS NULL OR NOT is_club_chairman(auth.uid(),$1) $$;
CREATE FUNCTION is_club_admin_or_permitted(uuid,uuid,text) RETURNS boolean LANGUAGE sql AS $$ SELECT is_club_chairman($1,$2) $$;
CREATE FUNCTION is_club_admin(uuid,uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT is_club_chairman($1,$2) $$;
CREATE FUNCTION has_club_permission(uuid,uuid,text) RETURNS boolean LANGUAGE sql AS $$ SELECT is_club_chairman($1,$2) $$;
CREATE FUNCTION chairman_banking_setup_change_allowed(text,text,jsonb,jsonb) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE TABLE clubs(id uuid PRIMARY KEY,chairman_member_id uuid);
CREATE TABLE profiles(id uuid PRIMARY KEY,email text);
CREATE TABLE member_fee_categories(id uuid PRIMARY KEY,club_id uuid,name text,annual_fee numeric,pro_rate boolean,due_month int,due_day int,active boolean,family_role text,family_additional_category_id uuid);
CREATE TABLE club_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid,user_id uuid,name text,email text,club_member_number text,id_number text,phone text,address text,gender text,skill_level int,plays_league boolean,role text DEFAULT 'member',fee_category_id uuid,billing_exempt boolean DEFAULT false,joined_at timestamptz DEFAULT now(),is_pending_approval boolean DEFAULT false,approved_at timestamptz,approved_by uuid,updated_at timestamptz);
CREATE TABLE league_associations(id uuid,club_id uuid,abbreviation text,active boolean);
CREATE TABLE national_body_fees(club_id uuid,fee_type text,body_name text,abbreviation text,fee_annual numeric,active boolean);
CREATE TABLE club_member_fee_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_member_id uuid,fee_type text,fee_label text,amount numeric,paid boolean DEFAULT false,paid_at timestamptz,season_year int,updated_at timestamptz,invoice_issued_at timestamptz,invoice_due_date date,is_pass_through boolean,paid_by_member_id uuid,family_group_id uuid,auto_seeded boolean,UNIQUE(club_member_id,fee_type,fee_label,season_year));
CREATE TABLE club_journal_entries(id uuid DEFAULT gen_random_uuid(),club_id uuid,club_member_id uuid,fee_payment_id uuid,account gl_account,debit numeric,credit numeric,description text,journal_ref uuid);
CREATE TABLE ledger_audit_log(club_id uuid,journal_ref uuid,action text,actor_user_id uuid,after_json jsonb,note text);
CREATE TABLE tournaments(id uuid PRIMARY KEY,club_id uuid,name text,entry_fee_cents int,payment_required boolean,start_date date,payment_timing text);
CREATE VIEW club_champs AS SELECT * FROM tournaments;
CREATE TABLE club_champs_registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),champ_id uuid,club_member_id uuid,status text,fee_status text,fee_paid_cents int,paid_at timestamptz,payment_ref text,fee_settled_via text,fee_settled_via_at timestamptz,fee_payment_id uuid,confirmed_at timestamptz,confirmed_by uuid,confirmation_source text,division_choices integer[],registration_status text,registration_source text);
CREATE TABLE club_family_groups(id uuid PRIMARY KEY,club_id uuid,primary_member_id uuid);
CREATE TABLE club_family_members(id uuid PRIMARY KEY,family_group_id uuid,club_member_id uuid,status text,approval_status text,is_new_member boolean,accepted_at timestamptz,approved_at timestamptz,approved_by uuid,confirmed_at timestamptz,updated_at timestamptz);
CREATE TABLE notifications(user_id uuid,club_member_id uuid,type text,title text,message text,url text);
CREATE FUNCTION resolve_host_billing_member(uuid,uuid) RETURNS uuid LANGUAGE sql AS $$ SELECT $1 $$;
CREATE FUNCTION champ_reg_own_due_cents(uuid) RETURNS int LANGUAGE sql AS $$ SELECT t.entry_fee_cents FROM tournaments t JOIN club_champs_registrations r ON r.champ_id=t.id WHERE r.id=$1 $$;
CREATE FUNCTION champ_member_fee_paid(uuid,uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION tournament_division_options(uuid,uuid) RETURNS jsonb LANGUAGE sql AS $$ SELECT '[{"group_number":1}]'::jsonb $$;
CREATE FUNCTION tournament_league_division_for(uuid,uuid) RETURNS int LANGUAGE sql AS $$ SELECT 1 $$;
CREATE FUNCTION apply_registration_division_choices(uuid) RETURNS void LANGUAGE plpgsql AS $$ BEGIN END $$;
CREATE FUNCTION member_is_delegate_of(uuid,uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION family_review_addition(uuid,boolean) RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN UPDATE club_family_members SET approval_status=CASE WHEN $2 THEN 'approved' ELSE 'rejected' END WHERE id=$1; IF $2 THEN PERFORM family_activate_approved($1); END IF; RETURN $2; END $$;
